{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "flip",
  "supportive_card_ids": ["C74", "C33", "C46"],
  "contradictory_card_ids": ["C01", "C11", "C17", "C03", "C16", "C04", "C10", "C02"],
  "prediction_basis_card_ids": ["C74", "C33"],
  "claims": [
    {
      "claim": "Pentazocine in control (non-cirrhotic) subjects has measured oral bioavailability 0.18 ± 0.05, below the 20% threshold; the high F in the cirrhosis context (0.68 ± 0.21) is condition-specific and does not transfer to the query's no-condition state.",
      "card_ids": ["C74"]
    },
    {
      "claim": "CDCA, a steroid, has only 20–40% systemic availability in humans due to 60–80% first-pass hepatic extraction, showing that steroid-like molecules can have low systemic F despite good absorption.",
      "card_ids": ["C33"]
    },
    {
      "claim": "Unlike the high-F reference steroids, which carry polar carboxyl/sugar/phenol groups, the query is a neutral, lipophilic enol-diketone steroid (logP 3.97, neutral fraction 0.99, no basic site) with unfavorable solubility prior; the only below-threshold measured F in the supplied records is for a similarly lipophilic drug with high first-pass metabolism (pentazocine control, 0.18 ± 0.05), supporting transfer of the low outcome.",
      "card_ids": ["C74"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "changed",
      "card_ids": ["C74", "C46"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "No matched oral vs IV AUC data for the query.",
    "Transfer from pentazocine (non-steroid) to the query is indirect; the query's first-pass metabolism is not directly measured.",
    "The high-F steroid references differ structurally (polar solubilizing groups) from the query.",
    "Solubility/dissolution of the query is estimated, not measured."
  ],
  "decision_summary": "L2 adds a below-threshold measured F (pentazocine control 0.18 ± 0.05, C74) and clarifies that the high F in the cirrhosis context is condition-specific. Combined with the query's lipophilic neutral steroid structure and unfavorable solubility prior, and the CDCA 20–40% systemic availability showing steroid first-pass extraction, the evidence better supports F < 20% than the indirect high-F transfers. Flip to low with moderate confidence."
}

